# Bundled from bots/mccfr_xc as player 'mccfr_xc': do not edit, re-bundle.
"""mccfr_xc: mccfr_xs plus a cluster specialist (#153).

Third strategy c1.npz: DBR response to the aggressive field cluster (burnerdrew2, Quad-J, karammasad, oskar,
Revanth, Sahith, shaswat, Utsav; k-means on node action rates). A second LLR (switch_c1.npz: cluster vs rest
of the field, both measured vs mccfr_x) picks it: blueprint switch first, else llr_c1 > on_c1 -> c1, and it
returns below off_c1. Everything below is the mccfr_xs design.

mccfr_xs: mccfr_x (DBR vs the field, #153) with an in-half safety switch to the mccfr blueprint.

mccfr_x exploits what the external field does but gives up ~0.5 bb/deal to a strong equilibrium player
(mccfr; Dushyant's blueprint bot plays alike). Every opponent action is scored at its betting-tree node:
    llr += log P_blueprint(a | node) - log P_field(a | node)
(switch.npz, train/build_switch_model.py: node-level action rates of mccfr and of the pooled field, both
measured against mccfr_x). After `min_actions` opponent actions, llr > `on` plays the blueprint, and it
returns to mccfr_x when llr < `off` (hysteresis). Calibration on full halves: mccfr / Dushyant +0.26 per
action, every external bot <= -0.06.

Opponent actions are all observed: the ones before our decisions come from action_history; the action
that ended the hand after our last decision is rebuilt in on_hand_end (fold if we won without showdown,
check/call if it went to showdown), and a hand we never acted in was an opponent fold on the button.
Strategies: strategy.npz (mccfr_x), blueprint.npz (bots/mccfr), same rows/buckets (abstraction.npz).
"""
_LIB = {'lib': '"""Helpers shared by bots: `from lib.equity import equity`. Import lib at module top level only\n(scripts/bundle.py inlines it and drops it from sys.modules once the bot has loaded)."""\n', 'lib.abstraction': '"""Abstract game for MCCFR (#32): the exact betting tree plus a card abstraction (buckets).\n\nPure and stateless (per AGENTS.md, `lib` is reloaded every half): module-level values are constants\nbuilt at import. Trainer (train/build_abstraction.py, train/train_mccfr.py) and bot import the SAME\nfunctions, so there is no train/play skew.\n\nBetting: stacks reset to 80 every hand and there are only 4 actions, so the real betting tree is\nsmall and fixed (cards never change legality). `BettingTree()` enumerates it with `game.Game`\nitself, so it follows any retuned constant in engine/game.py. No action abstraction or translation:\nevery real action sequence maps to exactly one tree node.\n\n    tree = BettingTree()\n    node = tree.node_of_obs(obs)          # decision id; tree.street[node], tree.actor[node], ...\n\nCards: per street `bucket(hole, board) -> int` (imperfect recall: only the current cards matter).\n    preflop  lossless suit-isomorphism classes (same key as lib.preflop.canon_key from #11)\n    flop     k-means on the CDF of per-runout river strength over SAMPLED turn+river runouts\n    turn     k-means on the CDF of river strength over ALL river cards\n    river    k-means on (equity vs a random hand, nut closeness)\nFeatures are computed on suit-canonical cards with fixed, seeded samples, so a bucket is a pure\nfunction of the hand\'s suit-isomorphism class: identical across processes and suit permutations.\nCentroids/edges/keys come from `CardAbstraction(path)` (an .npz written by train/build_abstraction.py).\n\n"River strength" of (hole, 5-card board): r = 1 - P(beat) - P(tie)/2 over all opponent 2-card\nholdings from the live cards (each scored with the Omaha rule on this board). An opponent\'s 5 cards\nhold 10 such pairs, so r is a cheap, exact, monotone-ish proxy for equity (rank corr. ~0.97 with\nexact equity vs a random hand); the river bucket uses a sampled exact equity on top.\n"""\n\nfrom __future__ import annotations\n\nimport math\nimport random\nfrom itertools import combinations, combinations_with_replacement\n\nimport numpy as np\n\nfrom evaluator import score_five\nfrom game import Action, Deal, Game, Street\n\n# ---------------------------------------------------------------------------\n# Betting tree\n# ---------------------------------------------------------------------------\n\nBUTTON, BIG_BLIND_SEAT = 0, 1  # tree "actor" values (relative seats; the real button alternates)\nFOLD_END, SHOWDOWN_END = 0, 1  # terminal kinds\n\n_DUMMY_DEAL = Deal(hole_cards=(tuple(range(5)), tuple(range(5, 10))), board=tuple(range(10, 15)))\n\n\nclass _TreeGame(Game):\n    """Game whose showdown skips hand evaluation: the betting tree never looks at cards."""\n\n    def _showdown(self) -> None:\n        self._finish(winner_seat=None, showdown=True)\n\n\ndef is_terminal(code: int) -> bool:\n    """children[n][a] codes: >= 0 decision id, < 0 terminal (`terminal_id(code)`), None illegal."""\n    return code < 0\n\n\ndef terminal_id(code: int) -> int:\n    return ~code\n\n\nclass BettingTree:\n    """Every decision node and terminal of one hand, seat-relative (actor 0 = button).\n\n    Decision ids are sorted by street, so a street\'s nodes are the contiguous range\n    `street_start[s] : street_start[s] + street_count[s]`; `street_index[n]` is n\'s index inside it.\n    Per decision node n: street, actor, pot (both players, incl. blinds), to_call, raises (this street),\n    legal (tuple of Action), children[n][a] (see `is_terminal`), history (tuple of Action from the root).\n    Per terminal t: term_kind, term_street (street of the last action), term_folder (actor who folded,\n    or -1), term_contrib (chips each actor put in; equal at a showdown).\n    """\n\n    def __init__(self) -> None:\n        nodes: list[tuple] = []  # (street, actor, pot, to_call, raises, legal, history)\n        kids: list[list] = []\n        terms: list[tuple] = []  # (kind, street, folder, contrib0, contrib1)\n\n        def visit(game: _TreeGame, history: tuple) -> int:\n            if game.is_terminal:\n                res = game.result()\n                last = res.history[-1]\n                folder = last.seat if last.action == Action.FOLD else -1\n                kind = FOLD_END if folder >= 0 else SHOWDOWN_END\n                c = game.contributed\n                if kind == SHOWDOWN_END and c[0] != c[1]:\n                    raise AssertionError("showdown with unequal contributions")\n                terms.append((kind, int(last.street), folder, c[0], c[1]))\n                return ~(len(terms) - 1)\n            seat = game.to_act\n            nid = len(nodes)\n            nodes.append((int(game.street), seat, game.pot, game._to_call(seat), game.raises_this_street,\n                          game.legal_actions(), history))\n            kids.append([None] * 4)\n            for a in game.legal_actions():\n                g = game.clone()\n                g.apply(a)\n                kids[nid][int(a)] = visit(g, history + (a,))\n            return nid\n\n        visit(_TreeGame(_DUMMY_DEAL, button_seat=BUTTON), ())\n\n        # Renumber decision nodes by (street, discovery order).\n        order = sorted(range(len(nodes)), key=lambda n: (nodes[n][0], n))\n        new_id = {old: new for new, old in enumerate(order)}\n        self.street = [nodes[o][0] for o in order]\n        self.actor = [nodes[o][1] for o in order]\n        self.pot = [nodes[o][2] for o in order]\n        self.to_call = [nodes[o][3] for o in order]\n        self.raises = [nodes[o][4] for o in order]\n        self.legal = [nodes[o][5] for o in order]\n        self.history = [nodes[o][6] for o in order]\n        self.children = [[None if c is None else (c if c < 0 else new_id[c]) for c in kids[o]] for o in order]\n        self.root = new_id[0]\n        self.term_kind = [t[0] for t in terms]\n        self.term_street = [t[1] for t in terms]\n        self.term_folder = [t[2] for t in terms]\n        self.term_contrib = [(t[3], t[4]) for t in terms]\n        self.street_count = [self.street.count(s) for s in range(4)]\n        self.street_start = [sum(self.street_count[:s]) for s in range(4)]\n        self.street_index = [n - self.street_start[self.street[n]] for n in range(len(self.street))]\n\n    @property\n    def num_nodes(self) -> int:\n        return len(self.street)\n\n    @property\n    def num_terminals(self) -> int:\n        return len(self.term_kind)\n\n    def next(self, node: int, action) -> int:\n        """Child code after `action` at decision node `node` (KeyError if illegal)."""\n        code = self.children[node][int(action)]\n        if code is None:\n            raise KeyError(f"{Action(action).name} is illegal at node {node}")\n        return code\n\n    def node_after(self, actions) -> int:\n        """Decision id reached by playing `actions` (Action ints) from the root. Raises if the\n        sequence is illegal or ends the hand."""\n        node = self.root\n        for a in actions:\n            node = self.next(node, a)\n            if is_terminal(node):\n                raise KeyError("the action sequence ends the hand")\n        return node\n\n    def node_of_obs(self, obs) -> int:\n        """Decision id of the current observation; checks it against obs (street, seat, legal, pot)."""\n        node = self.node_after([a.action for a in obs.action_history])\n        expect_actor = BUTTON if obs.is_button else BIG_BLIND_SEAT\n        if (self.street[node] != int(obs.street) or self.actor[node] != expect_actor\n                or self.pot[node] != obs.pot or tuple(self.legal[node]) != tuple(obs.legal_actions)):\n            raise ValueError(f"observation does not match tree node {node}")\n        return node\n\n    def terminal_value(self, t: int, winner: int | None) -> tuple[int, int]:\n        """Chips won by (actor 0, actor 1) at terminal t. `winner` (actor id, None = split) is only\n        used at a showdown; a fold terminal ignores it."""\n        c0, c1 = self.term_contrib[t]\n        if self.term_kind[t] == FOLD_END:\n            return (-c0, c0) if self.term_folder[t] == BUTTON else (c1, -c1)\n        if winner is None:\n            return (0, 0)\n        return (c1, -c1) if winner == BUTTON else (-c0, c0)\n\n\n# ---------------------------------------------------------------------------\n# Vectorized Omaha evaluator (exact; matches evaluator.omaha_score)\n# ---------------------------------------------------------------------------\n# A 5-card score depends only on the multiset of ranks and whether it is a flush. Ranks are encoded\n# additively (sum of 5**rank; a rank appears at most 4 times), so pair + triple keys simply add.\n\n_POW5 = [5 ** r for r in range(9)]\n_RKEY = np.array([_POW5[c >> 2] for c in range(36)], np.int64)\n_SUIT = np.arange(36, dtype=np.int64) & 3\n\n\ndef _build_score_table() -> np.ndarray:\n    # Sized for any 5 rank keys (5 * 5**8): batched runouts also score masked-out pairs that reuse a\n    # runout card; those entries stay 0 and are ignored by the caller.\n    t = np.zeros((2, 5 * _POW5[8] + 1), np.int32)\n    for ranks in combinations_with_replacement(range(9), 5):\n        if max(ranks.count(r) for r in ranks) > 4:\n            continue\n        key = sum(_POW5[r] for r in ranks)\n        seen: dict[int, int] = {}\n        cards = []\n        for r in ranks:  # repeated ranks take different suits, so these cards are never a flush\n            s = seen.get(r, 0)\n            seen[r] = s + 1\n            cards.append(r * 4 + s)\n        if len(set(ranks)) == 5:\n            t[1, key] = score_five([r * 4 for r in ranks])\n            cards[1] = ranks[1] * 4 + 1\n        t[0, key] = score_five(cards)\n    return t\n\n\n_SCORE = _build_score_table()\nPAIRS5 = np.array(list(combinations(range(5), 2)), np.intp)    # 10 ways to pick 2 of 5 hole cards\nTRIPLES5 = np.array(list(combinations(range(5), 3)), np.intp)  # 10 ways to pick 3 of 5 board cards\n\n\ndef _parts(cards: np.ndarray, size: int, no_flush: int) -> tuple[np.ndarray, np.ndarray]:\n    """(rank key, flush code) of card groups in the last axis; code = the suit if all suited."""\n    key = _RKEY[cards].sum(-1)\n    s = _SUIT[cards]\n    suited = (s == s[..., :1]).all(-1)\n    return key, np.where(suited, s[..., 0], no_flush)\n\n\ndef best_scores(pairs: np.ndarray, triples: np.ndarray) -> np.ndarray:\n    """Best Omaha score of each 2-card pair with each set of 10 board triples.\n\n    pairs: (..., P, 2) cards; triples: (..., 10, 3) cards (broadcast against pairs\' leading dims).\n    Returns (..., P): max over the 10 triples of score(pair + triple)."""\n    pk, pc = _parts(pairs, 2, -1)\n    tk, tc = _parts(triples, 3, -2)\n    flush = (pc[..., :, None] == tc[..., None, :]).astype(np.intp)\n    return _SCORE[flush, pk[..., :, None] + tk[..., None, :]].max(-1)\n\n\ndef omaha_score_np(hole, board) -> int:\n    """Same value as evaluator.omaha_score (testing / one-off use)."""\n    h, b = np.asarray(hole, np.intp), np.asarray(board, np.intp)\n    return int(best_scores(h[PAIRS5], b[TRIPLES5]).max())\n\n\n# ---------------------------------------------------------------------------\n# Suit canonicalization\n# ---------------------------------------------------------------------------\n\ndef preflop_key(hole) -> int:\n    """Suit-isomorphism class key of 5 hole cards (identical to lib.preflop.canon_key in #11)."""\n    m = [0, 0, 0, 0]\n    for c in hole:\n        m[c & 3] |= 1 << (c >> 2)\n    m.sort(reverse=True)\n    return (m[0] << 27) | (m[1] << 18) | (m[2] << 9) | m[3]\n\n\ndef canonical(hole, board) -> tuple[tuple[int, ...], tuple[int, ...], int]:\n    """Relabel suits so isomorphic (hole, board-as-a-set) inputs give identical cards.\n\n    Suits are ordered by (board rank mask, hole rank mask), descending; suits with equal masks are\n    interchangeable, so ties don\'t matter. Returns (hole, board) sorted, plus an int key of the class."""\n    hm, bm = [0, 0, 0, 0], [0, 0, 0, 0]\n    for c in hole:\n        hm[c & 3] |= 1 << (c >> 2)\n    for c in board:\n        bm[c & 3] |= 1 << (c >> 2)\n    order = sorted(range(4), key=lambda s: (bm[s], hm[s]), reverse=True)\n    relabel = [0] * 4\n    for new, old in enumerate(order):\n        relabel[old] = new\n    h = tuple(sorted((c & ~3) | relabel[c & 3] for c in hole))\n    b = tuple(sorted((c & ~3) | relabel[c & 3] for c in board))\n    key = 0\n    for s in order:\n        key = (key << 18) | (bm[s] << 9) | hm[s]\n    return h, b, key\n\n\n# ---------------------------------------------------------------------------\n# Strength features\n# ---------------------------------------------------------------------------\n\nFLOP_RUNOUTS = 24       # sampled turn+river runouts per flop (seeded by the canonical class)\nRIVER_OPP_SAMPLES = 1024  # fixed opponent 5-card hands for the river equity estimate\nRIVER_OPP_SEED = 0\nFEATURE_VERSION = 1     # bump when any feature definition above/below changes\n\n_PAIRS = {n: np.array(list(combinations(range(n), 2)), np.intp) for n in (26, 27, 28)}\n_BOARD_TRIPLES = {n: np.array(list(combinations(range(n), 3)), np.intp) for n in (3, 4)}\n_BOARD_PAIRS = {n: np.array(list(combinations(range(n), 2)), np.intp) for n in (3, 4)}\n_PAIR_INDEX26 = {p: i for i, p in enumerate(map(tuple, _PAIRS[26].tolist()))}\n\n\ndef _opp_subsets() -> np.ndarray:\n    """RIVER_OPP_SAMPLES random 5-subsets of the 26 live cards, as indices of their 10 pairs."""\n    rng = random.Random(RIVER_OPP_SEED)\n    out = np.empty((RIVER_OPP_SAMPLES, 10), np.intp)\n    for i in range(RIVER_OPP_SAMPLES):\n        s = sorted(rng.sample(range(26), 5))\n        out[i] = [_PAIR_INDEX26[(s[a], s[b])] for a, b in combinations(range(5), 2)]\n    return out\n\n\n_OPP_SUB = _opp_subsets()\n_LOG_PAIRS = math.log(1 + 325)\n\n\ndef _unseen(hole, board) -> np.ndarray:\n    dead = set(hole) | set(board)\n    return np.array([c for c in range(36) if c not in dead], np.intp)\n\n\ndef _strength(opp: np.ndarray, me: np.ndarray, valid: np.ndarray) -> np.ndarray:\n    """r = 1 - P(beat) - P(tie)/2 per runout row, over the valid opponent pairs."""\n    beat = ((opp > me[:, None]) & valid).sum(1)\n    tie = ((opp == me[:, None]) & valid).sum(1)\n    return 1.0 - (beat + 0.5 * tie) / valid.sum(1)\n\n\ndef _max_over(pk, pc, tk, tc) -> np.ndarray:\n    """Best score of each pair (keys pk, codes pc: (..., P)) over triples (tk, tc: (..., T))."""\n    flush = (pc[..., :, None] == tc[..., None, :]).astype(np.intp)\n    return _SCORE[flush, pk[..., :, None] + tk[..., None, :]].max(-1)\n\n\ndef _fast_runout_strength(hole, board, unseen: np.ndarray, extra: np.ndarray) -> np.ndarray:\n    """Same values as `runout_strength_reference`, without rescoring the triples runouts share.\n\n    Triples of the final board split by how many runout cards they use: 0 (shared by every runout),\n    1 (depend on one unseen card: computed once per unseen card) and 2 (flop only: per runout)."""\n    b = np.asarray(board, np.intp)\n    pairs_idx = _PAIRS[len(unseen)]\n    allp = np.concatenate([unseen[pairs_idx], np.asarray(hole, np.intp)[PAIRS5]])  # opp pairs, then ours\n    pk, pc = _parts(allp, 2, -1)\n    n_opp = len(pairs_idx)\n\n    t0 = b[_BOARD_TRIPLES[len(b)]]\n    best = _max_over(pk, pc, *_parts(t0, 3, -2))                                   # (P+10,)\n\n    bp = b[_BOARD_PAIRS[len(b)]]                                                   # board pairs\n    bk, bc = _parts(bp, 2, -1)\n    su = _SUIT[unseen]\n    tk1 = _RKEY[unseen][:, None] + bk[None, :]\n    tc1 = np.where(bc[None, :] == su[:, None], su[:, None], -2)\n    single = _max_over(pk[None], pc[None], tk1, tc1)                               # (U, P+10)\n\n    tot = np.maximum(best[None], single[extra[:, 0]])                              # (R, P+10)\n    valid = (pairs_idx[None, :, 0] != extra[:, :1]) & (pairs_idx[None, :, 1] != extra[:, :1])\n    if extra.shape[1] == 2:\n        t, r = unseen[extra[:, 0]], unseen[extra[:, 1]]\n        tot = np.maximum(tot, single[extra[:, 1]])\n        tk2 = (_RKEY[t] + _RKEY[r])[:, None] + _RKEY[b][None, :]\n        st, sr = _SUIT[t][:, None], _SUIT[r][:, None]\n        tc2 = np.where((st == sr) & (sr == _SUIT[b][None, :]), st, -2)\n        tot = np.maximum(tot, _max_over(pk[None], pc[None], tk2, tc2))\n        e = extra[:, 1:]\n        valid &= (pairs_idx[None, :, 0] != e) & (pairs_idx[None, :, 1] != e)\n    return _strength(tot[:, :n_opp], tot[:, n_opp:].max(1), valid)\n\n\ndef runout_strength_reference(hole, board, unseen: np.ndarray, extra: np.ndarray) -> np.ndarray:\n    """River strength r for each runout (straightforward version, kept for tests). extra: (R, k)\n    indices into `unseen` completing the board to 5 cards. Opponent pairs are all pairs of unseen\n    cards not used by that runout (325 each)."""\n    pairs_idx = _PAIRS[len(unseen)]                          # (P, 2) indices into unseen\n    boards = np.concatenate([np.broadcast_to(np.asarray(board, np.intp), (len(extra), len(board))),\n                             unseen[extra]], axis=1)          # (R, 5)\n    triples = boards[:, TRIPLES5]                             # (R, 10, 3)\n    opp = best_scores(unseen[pairs_idx][None], triples)       # (R, P)\n    me = best_scores(np.asarray(hole, np.intp)[PAIRS5][None], triples).max(-1)  # (R,)\n    valid = np.ones((len(extra), len(pairs_idx)), bool)\n    for j in range(extra.shape[1]):\n        e = extra[:, j][:, None]\n        valid &= (pairs_idx[None, :, 0] != e) & (pairs_idx[None, :, 1] != e)\n    return _strength(opp, me, valid)\n\n\ndef river_features(hole, board) -> np.ndarray:\n    """[equity vs a random hand (fixed sample), nut closeness]; board has 5 cards."""\n    hole, board, _ = canonical(hole, board)\n    live = _unseen(hole, board)\n    triples = np.asarray(board, np.intp)[TRIPLES5]\n    opp_pairs = best_scores(live[_PAIRS[26]], triples)       # (325,)\n    me = best_scores(np.asarray(hole, np.intp)[PAIRS5], triples).max()\n    opp = opp_pairs[_OPP_SUB].max(1)\n    eq = (opp < me).mean() + 0.5 * (opp == me).mean()\n    beat = (opp_pairs > me).sum()\n    nut = 1.0 - math.log1p(beat) / _LOG_PAIRS\n    return np.array([eq, nut])\n\n\ndef turn_strengths(hole, board) -> np.ndarray:\n    """River strength after each of the 27 possible river cards (exact enumeration)."""\n    hole, board, _ = canonical(hole, board)\n    unseen = _unseen(hole, board)\n    return _fast_runout_strength(hole, board, unseen, np.arange(len(unseen))[:, None])\n\n\ndef flop_strengths(hole, board, runouts: int = FLOP_RUNOUTS) -> np.ndarray:\n    """River strength over `runouts` turn+river runouts, sampled with a seed from the canonical class."""\n    hole, board, key = canonical(hole, board)\n    unseen = _unseen(hole, board)\n    rng = random.Random(key)\n    pick = rng.sample(range(len(_PAIRS[len(unseen)])), runouts)\n    return _fast_runout_strength(hole, board, unseen, _PAIRS[len(unseen)][sorted(pick)])\n\n\ndef cdf_features(strengths: np.ndarray, edges: np.ndarray) -> np.ndarray:\n    """Cumulative histogram of strengths at the inner bin edges (L2 on CDFs ~ earth mover\'s)."""\n    return (strengths[None, :] < np.asarray(edges)[:, None]).mean(1)\n\n\ndef street_features(hole, board, edges: np.ndarray | None = None) -> np.ndarray:\n    """Feature vector used for k-means/bucketing at this street (board of 3, 4 or 5 cards)."""\n    if len(board) == 5:\n        return river_features(hole, board)\n    s = flop_strengths(hole, board) if len(board) == 3 else turn_strengths(hole, board)\n    return cdf_features(s, edges)\n\n\ndef nearest(centroids: np.ndarray, x: np.ndarray) -> int:\n    """Index of the nearest centroid (squared L2; lowest index on ties)."""\n    return int(np.argmin(((centroids - x) ** 2).sum(1)))\n\n\n# ---------------------------------------------------------------------------\n# Loaded abstraction\n# ---------------------------------------------------------------------------\n\nclass CardAbstraction:\n    """Bucket mapping loaded from an .npz written by train/build_abstraction.py. Load at import.\n\n    Arrays: preflop_keys (sorted class keys), flop_edges/turn_edges, flop/turn/river_centroids, and a\n    config that must match this module\'s feature constants (refuses to load on train/play skew)."""\n\n    def __init__(self, path) -> None:\n        z = np.load(path)\n        expect = np.array([FEATURE_VERSION, FLOP_RUNOUTS, RIVER_OPP_SAMPLES, RIVER_OPP_SEED])\n        if not np.array_equal(z["config"], expect):\n            raise ValueError(f"abstraction {path} was built with features {z[\'config\']}, this code is {expect}")\n        self.preflop_keys = z["preflop_keys"]\n        self.edges = {Street.FLOP: z["flop_edges"], Street.TURN: z["turn_edges"]}\n        self.centroids = {Street.FLOP: z["flop_centroids"], Street.TURN: z["turn_centroids"],\n                          Street.RIVER: z["river_centroids"]}\n\n    def num_buckets(self, street) -> int:\n        return len(self.preflop_keys) if street == Street.PREFLOP else len(self.centroids[Street(street)])\n\n    def bucket(self, hole, board) -> int:\n        """Bucket of (hole, board) on the street implied by len(board)."""\n        if not board:\n            key = preflop_key(hole)\n            i = int(np.searchsorted(self.preflop_keys, key))\n            if i >= len(self.preflop_keys) or int(self.preflop_keys[i]) != key:\n                raise KeyError(f"unknown preflop class {key}")\n            return i\n        street = {3: Street.FLOP, 4: Street.TURN, 5: Street.RIVER}[len(board)]\n        x = street_features(hole, board, self.edges.get(street))\n        return nearest(self.centroids[street], x)\n', 'lib.archetype_clf': '"""Opponent archetype classifier (category 5.2, #17): nit / station / maniac / naive_equity / holdem,\n"balanced" when nothing fits, "unknown" until MIN_HANDS.\n\nUsage (state in memory; lib holds none):\n\n    new_half:     memory["clf"] = archetype_clf.new_state()\n    on_hand_end:  oppstats.hand_end(memory["opp"], result)\n                  archetype_clf.update(memory["clf"], memory["opp"], memory["rng"])   # new showdowns only\n    read:         label, conf = archetype_clf.classify(memory["clf"], memory["opp"])\n\nFeatures (features()):\n  vpip, pfr, fold_raise, call_down, agg_freq   lib.oppstats rates, both seats\n  auc        P(eq of a postflop raise > eq of a postflop check/call where a raise was legal), from\n             showdowns; eq = opponent\'s equity vs a random hand. ~1 for threshold (naive-equity) bots,\n             ~0.5 for bots that ignore their cards.\n  holdem     AUC of the same decisions under Hold\'em-brained equity (best 5 of all 10 cards, Hold\'em\n             category order) minus auc: > 0 when the misconception explains their raises better.\nModel: Gaussian naive Bayes, per-class means/stds in MODEL (fitted by scripts/fit_archetype_clf.py on\nlabelled pool bots). Showdown features are skipped while they have fewer than MIN_SD decisions.\nNever raises.\n"""\n\nimport math\nimport random\nfrom itertools import combinations\n\nimport numpy as np\n\nfrom game import Action\nfrom lib import oppstats\nfrom lib.equity import _KEYS, _SCORES, _best\nfrom lib.threshold_fit import decisions\n\nLABELS = ("nit", "station", "maniac", "naive_equity", "holdem")\nFEATURES = ("vpip", "pfr", "fold_raise", "call_down", "agg_freq", "auc", "holdem")\nRATE_FEATURES = FEATURES[:5]\nMIN_HANDS = 30      # "unknown" below this\nMIN_SD = 8          # postflop showdown decisions (with both classes) before auc/holdem count\nMIN_CONF = 0.6      # below this posterior: "balanced"\nSAMPLES = 32  # ~3.7 ms per showdown in update(); 16 costs ~3 points of accuracy\nDECISION_CAP = 400\n_RAISES = (Action.RAISE_HALF, Action.RAISE_POT)\n\n# Hold\'em category order: straight <-> trips, flush <-> full house (short deck ranks them the other way)\n_CAT = np.array([0, 1, 2, 4, 3, 6, 5, 7, 8], dtype=np.int64)\n_HSCORES = (_CAT[_SCORES >> 20] << 20) | (_SCORES & 0xFFFFF)\n_C5 = np.array(list(combinations(range(10), 5)))  # (252, 5)\n\n# Fitted by scripts/fit_archetype_clf.py: label -> {feature: (mean, std)}\nMODEL = {\n    \'nit\': {\'vpip\': (0.4353, 0.2308), \'pfr\': (0.0264, 0.06), \'fold_raise\': (0.6547, 0.2796), \'call_down\': (0.2702, 0.2203), \'agg_freq\': (0.0846, 0.0743), \'auc\': (0.9621, 0.06), \'holdem\': (-0.0572, 0.06)},\n    \'station\': {\'vpip\': (0.7098, 0.06), \'pfr\': (0.0112, 0.06), \'fold_raise\': (0.0672, 0.06), \'call_down\': (0.8994, 0.0755), \'agg_freq\': (0.0391, 0.06), \'auc\': (0.9767, 0.06), \'holdem\': (-0.0829, 0.0668)},\n    \'maniac\': {\'vpip\': (0.9288, 0.1033), \'pfr\': (0.8642, 0.1655), \'fold_raise\': (0.0975, 0.1159), \'call_down\': (0.3441, 0.115), \'agg_freq\': (0.8408, 0.1266), \'auc\': (0.6558, 0.1256), \'holdem\': (-0.0347, 0.06)},\n    \'naive_equity\': {\'vpip\': (0.5177, 0.1302), \'pfr\': (0.2143, 0.155), \'fold_raise\': (0.3068, 0.06), \'call_down\': (0.5163, 0.0863), \'agg_freq\': (0.2719, 0.138), \'auc\': (0.8972, 0.06), \'holdem\': (-0.0606, 0.06)},\n    \'holdem\': {\'vpip\': (0.4824, 0.06), \'pfr\': (0.159, 0.06), \'fold_raise\': (0.3492, 0.0617), \'call_down\': (0.4763, 0.06), \'agg_freq\': (0.2346, 0.06), \'auc\': (0.8054, 0.0719), \'holdem\': (0.0352, 0.0949)},\n}\n\n\ndef new_state() -> dict:\n    return {"done": -1, "dec": [], "tells": {}, "errors": 0, "last_error": None}\n\n\ndef _fail(s: dict, e: Exception) -> None:\n    try:\n        s["errors"] = s.get("errors", 0) + 1\n        s["last_error"] = f"{type(e).__name__}: {e}"\n    except Exception:  # noqa: BLE001\n        pass\n\n\ndef _best5_holdem(bits10):\n    """(S,10) card bits -> (S,) best 5-of-10 score under Hold\'em category order."""\n    masks = bits10[:, _C5].sum(axis=2)  # distinct bits: sum == or\n    return _HSCORES[np.searchsorted(_KEYS, masks)].max(axis=1)\n\n\ndef _equities(hole, board, rng: random.Random, samples: int) -> tuple[float, float]:\n    """(true Omaha equity, Hold\'em-brained equity) vs a random hand, on the same samples."""\n    dead = set(hole) | set(board)\n    live = [c for c in range(36) if c not in dead]\n    need = 10 - len(board)\n    draws = np.array([rng.sample(live, need) for _ in range(samples)], dtype=np.int64)\n    one = np.int64(1)\n    full = np.concatenate([np.broadcast_to(np.array(board, dtype=np.int64), (samples, len(board))),\n                           draws[:, 5:]], axis=1)\n    me_h = np.broadcast_to(np.array(hole, dtype=np.int64), (samples, 5))\n    opp_h = draws[:, :5]\n    me, op = _best(one << me_h, one << full), _best(one << opp_h, one << full)\n    true = float(((me > op) + 0.5 * (me == op)).mean())\n    me2 = _best5_holdem(one << np.concatenate([me_h, full], axis=1))\n    op2 = _best5_holdem(one << np.concatenate([opp_h, full], axis=1))\n    return true, float(((me2 > op2) + 0.5 * (me2 == op2)).mean())\n\n\ndef update(s: dict, stats: dict, rng: random.Random | None = None, samples: int = SAMPLES) -> None:\n    """Score postflop decisions of every new showdown in the oppstats log."""\n    try:\n        rng = rng or random.Random(0)\n        for rec in stats["showdowns"]:\n            if rec["hand"] <= s["done"] or rec["opp_seat"] is None:\n                continue\n            hole, board = list(rec["opp_hole"]), list(rec["board"])\n            for st, blen, _to_call, _pot, legal, action in decisions(rec):\n                if st > 0 and legal:\n                    t, h = _equities(hole, board[:blen], rng, samples)\n                    s["dec"].append((round(t, 4), round(h, 4), action in _RAISES))\n            s["done"] = rec["hand"]\n            s["tells"] = None\n        if len(s["dec"]) > DECISION_CAP:\n            del s["dec"][: len(s["dec"]) - DECISION_CAP]\n        if s.get("tells") is None:\n            s["tells"] = _tells(s["dec"])\n    except Exception as e:  # noqa: BLE001\n        _fail(s, e)\n\n\ndef auc(pos, neg) -> float:\n    """P(pos > neg) + 0.5 P(tie) (Mann-Whitney), O(n log n)."""\n    neg = np.sort(np.asarray(neg, dtype=float))\n    pos = np.asarray(pos, dtype=float)\n    lo, hi = np.searchsorted(neg, pos, "left"), np.searchsorted(neg, pos, "right")\n    return float((lo + 0.5 * (hi - lo)).sum() / (len(pos) * len(neg)))\n\n\ndef features(s: dict, stats: dict) -> dict:\n    """{feature: value}; auc/holdem absent until MIN_SD decisions with raises and non-raises."""\n    c = oppstats._counts(stats, None, None)  # one pass instead of one per feature (estimate() redoes it)\n    f = {k: oppstats._value(k, c)[0] for k in RATE_FEATURES}\n    f.update(s.get("tells") or {})\n    return f\n\n\ndef _tells(dec: list[tuple]) -> dict:\n    pos = [d for d in dec if d[2]]\n    neg = [d for d in dec if not d[2]]\n    if len(dec) < MIN_SD or not pos or not neg:\n        return {}\n    a = auc([d[0] for d in pos], [d[0] for d in neg])\n    return {"auc": a, "holdem": auc([d[1] for d in pos], [d[1] for d in neg]) - a}\n\n\ndef posterior(f: dict, model: dict | None = None) -> dict:\n    """label -> posterior probability (uniform prior) under the Gaussian naive Bayes MODEL."""\n    model = model or MODEL\n    ll = {}\n    for lab, params in model.items():\n        x = 0.0\n        for k, v in f.items():\n            m, sd = params[k]\n            x += -0.5 * ((v - m) / sd) ** 2 - math.log(sd)\n        ll[lab] = x\n    top = max(ll.values())\n    z = sum(math.exp(v - top) for v in ll.values())\n    return {lab: math.exp(v - top) / z for lab, v in ll.items()}\n\n\ndef classify(s: dict, stats: dict, model: dict | None = None) -> tuple[str, float]:\n    """(label, confidence). "unknown" (0.0) before MIN_HANDS, "balanced" below MIN_CONF."""\n    try:\n        if oppstats.hands(stats) < MIN_HANDS or not (model or MODEL):\n            return "unknown", 0.0\n        post = posterior(features(s, stats), model)\n        lab = max(post, key=post.get)\n        return (lab if post[lab] >= MIN_CONF else "balanced"), post[lab]\n    except Exception as e:  # noqa: BLE001\n        _fail(s, e)\n        return "unknown", 0.0\n', 'lib.commitment': '"""One-street EV comparison for legal raises that exhaust most of our stack.\n\nEquity is against the caller, and fold probability is conditional on raising.\nThe caller model is supplied by the policy; neither value is inferred here.\n"""\nfrom game import Action\n\n\ndef commitment_values(obs, eq, fold_probability=0.0, max_remaining_fraction=0.0):\n    """Return chip EVs from this decision, or None outside commitment spots.\n\n    CHECK_CALL assumes a checkdown after a non-all-in call. A raise assumes\n    fold or call then checkdown. At default fraction zero, raises are genuine\n    all-ins, so their showdown accounting has no unmodelled future bets.\n    Nonzero fractions explicitly opt into an approximate checkdown model.\n    """\n    if not 0 <= eq <= 1 or not 0 <= fold_probability <= 1:\n        raise ValueError(\'equity and fold probability must be in [0, 1]\')\n    if not 0 <= max_remaining_fraction <= 1:\n        raise ValueError(\'remaining fraction must be in [0, 1]\')\n    call_cost = min(obs.to_call, obs.my_stack)\n    values = {Action.CHECK_CALL: eq * (obs.pot + call_cost) - call_cost}\n    if Action.FOLD in obs.legal_actions:\n        values[Action.FOLD] = 0.0\n    committed = obs.opp_stack == 0\n    for action in (Action.RAISE_HALF, Action.RAISE_POT):\n        if action not in obs.legal_actions:\n            continue\n        cost = obs.raise_to[action] - obs.my_bet\n        if obs.my_stack - cost > max_remaining_fraction * obs.my_stack:\n            continue\n        committed = True\n        response_cost = min(obs.opp_stack, max(0, obs.raise_to[action] - obs.opp_bet))\n        called_ev = eq * (obs.pot + cost + response_cost) - cost\n        values[action] = fold_probability * obs.pot + (1 - fold_probability) * called_ev\n    return values if committed else None\n\n\ndef commitment_action(obs, eq, fallback, fold_probability=0.0, max_remaining_fraction=0.0,\n                      min_gain=0.0):\n    """Prefer the fallback on ties; change only for a strict EV improvement."""\n    values = commitment_values(obs, eq, fold_probability, max_remaining_fraction)\n    if values is None:\n        return fallback\n    # Fallback can be a noncommitting raise outside our model: keep it.\n    if fallback not in values:\n        return fallback\n    best = max(values, key=lambda action: (values[action], action == fallback, int(action)))\n    return best if values[best] > values[fallback] + min_gain else fallback\n', 'lib.equity': '"""Monte Carlo equity against one uniformly random opponent hand."""\n\nfrom itertools import combinations\n\nimport numpy as np\n\nfrom evaluator import get_table\n\nDECK = range(36)\n_PAIRS = tuple(combinations(range(5), 2))\n_TRIPLES = tuple(combinations(range(5), 3))\n_PI, _PJ = (np.array(x) for x in zip(*_PAIRS))\n_TI, _TJ, _TK = (np.array(x) for x in zip(*_TRIPLES))\n\n\ndef _build_lookup():\n    """Sorted card-mask keys + aligned scores: the evaluator table as numpy arrays (built at import)."""\n    table = get_table()\n    keys = np.fromiter(table.keys(), dtype=np.int64, count=len(table))\n    scores = np.fromiter(table.values(), dtype=np.int64, count=len(table))\n    order = np.argsort(keys)\n    return keys[order], scores[order]\n\n\n_KEYS, _SCORES = _build_lookup()\n\n\ndef _best(hole_bits, board_bits):\n    """(S,5) bit arrays -> (S,) best Omaha score; same value as evaluator.omaha_score per row."""\n    hm = hole_bits[:, _PI] | hole_bits[:, _PJ]                      # (S,10)\n    bm = board_bits[:, _TI] | board_bits[:, _TJ] | board_bits[:, _TK]  # (S,10)\n    masks = (hm[:, :, None] | bm[:, None, :]).reshape(len(hm), 100)\n    return _SCORES[np.searchsorted(_KEYS, masks)].max(axis=1)\n\n\ndef equity(hole, board, rng, samples: int) -> float:\n    """Share of the pot we\'d win at showdown vs a random 5-card hand (ties count half).\n    Fixed `samples` keeps it deterministic for a seeded rng. All samples are scored in one\n    numpy batch. Bit-identical to the plain omaha_score loop (same rng calls, same scores)."""\n    dead = set(hole) | set(board)\n    live = [c for c in DECK if c not in dead]\n    need = 5 + 5 - len(board)\n    sample = rng.sample\n    draws = np.array([sample(live, need) for _ in range(samples)], dtype=np.int64)\n    bits = np.int64(1) << draws                                       # (S,need)\n    extra = bits[:, 5:]\n    board_bits = np.concatenate(\n        [np.broadcast_to(np.int64(1) << np.array(board, dtype=np.int64), (samples, len(board))), extra], axis=1)\n    my_bits = np.broadcast_to(np.int64(1) << np.array(hole, dtype=np.int64), (samples, 5))\n    me = _best(my_bits, board_bits)\n    opp = _best(bits[:, :5], board_bits)\n    return float(((me > opp).sum() + 0.5 * (me == opp).sum())) / samples\n', 'lib.features': '"""Canonical observation encoders, shared by training scripts and bots so train/play can\'t drift.\n\nPure Python lists of floats: wrap them with torch.tensor / numpy.asarray as needed.\nChanging an encoder changes its output for every model trained on it: add a new function\n(cards_v2, ...) instead of editing one a shipped model uses.\n"""\n\nfrom game import RAISE_CAP_PER_STREET, STARTING_STACK, Action, Street\nfrom lib import oppstats\n\nCARD_DIM = 36 + 36 + 4                # hole one-hot, board one-hot, street one-hot\nHOLE_DIM = 9 + 4 + 6                  # rank counts, suit counts, shape summary\nSTATE_DIM = 10 + 4 * 2                # bets/stacks/position + raises per street per player\nOBS_DIM = CARD_DIM + HOLE_DIM + STATE_DIM\n\n\ndef cards(hole, board) -> list[float]:\n    """One-hot hole cards and board, plus the street implied by the board size."""\n    x = [0.0] * CARD_DIM\n    for c in hole:\n        x[c] = 1.0\n    for c in board:\n        x[36 + c] = 1.0\n    x[72 + {0: 0, 3: 1, 4: 2, 5: 3}[len(board)]] = 1.0\n    return x\n\n\ndef hole_shape(hole) -> list[float]:\n    """Preflop features: rank and suit counts, pairs, trips, max suit, longest rank run, high cards."""\n    ranks, suits = [0] * 9, [0] * 4\n    for c in hole:\n        ranks[c >> 2] += 1\n        suits[c & 3] += 1\n    run = best = 0\n    for r in [ranks[8]] + ranks:  # ace also plays low (A-6-7-8-9)\n        run = run + 1 if r else 0\n        best = max(best, run)\n    pairs = sum(r >= 2 for r in ranks)\n    return ([r / 4 for r in ranks] + [s / 5 for s in suits]\n            + [pairs / 2, float(any(r >= 3 for r in ranks)), max(suits) / 5,\n               sum(s >= 2 for s in suits) / 2, best / 5, sum(ranks[6:]) / 5])\n\n\ndef state(obs) -> list[float]:\n    """Betting state, normalized by the starting stack, plus raise counts by street and player."""\n    s = STARTING_STACK\n    raises = [0.0] * 8\n    for a in obs.action_history:\n        if a.action in (Action.RAISE_HALF, Action.RAISE_POT):\n            raises[int(a.street) * 2 + (0 if a.is_me else 1)] += 1 / RAISE_CAP_PER_STREET\n    to_call = obs.to_call\n    return [obs.pot / (2 * s), to_call / s, obs.my_bet / s, obs.opp_bet / s, obs.my_stack / s,\n            obs.opp_stack / s, float(obs.is_button), obs.raises_this_street / RAISE_CAP_PER_STREET,\n            to_call / (obs.pot + to_call) if to_call else 0.0, float(obs.street == Street.PREFLOP)] + raises\n\n\ndef encode(obs) -> list[float]:\n    """Everything above: OBS_DIM floats."""\n    return cards(obs.hole_cards, obs.board) + hole_shape(obs.hole_cards) + state(obs)\n\n\n# ----- opponent model (lib.oppstats) -----\n\nOPP_DIM = oppstats.VECTOR_DIM  # 56\n\n\ndef opp_stats(stats) -> list[float]:\n    """Opponent-stats features from a lib.oppstats dict (e.g. memory["opp"]): OPP_DIM floats.\n    Order is documented in oppstats.vector (3 groups: opp on button / in BB / both, each\n    8 stats as value+confidence; then agg_freq and fold_raise for each of the 4 streets)."""\n    return oppstats.vector(stats)\n', 'lib.nuts': '"""Exact made-hand nuts, card-removal blockers and one-card nut outs.\n\nAll comparisons use exactly two private and three public cards. A nut out\nmeans nuts on the *next* board, not a guarantee against a later redraw.\n"""\nfrom dataclasses import dataclass\nfrom itertools import combinations\nfrom array import array\n\nfrom evaluator import get_table\n\n\n@dataclass(frozen=True)\nclass NutInfo:\n    score: int\n    opponent_best: int\n    public_best: int\n    blocked_nut_pairs: int\n    public_nut_pairs: int\n\n    @property\n    def is_nuts(self):\n        """No legal opponent hand can beat us (ties are allowed)."""\n        return self.score >= self.opponent_best\n\n    @property\n    def blocker_fraction(self):\n        return self.blocked_nut_pairs / self.public_nut_pairs\n\n\ndef build_index():\n    """Immutable-by-convention packed pair rankings for all public triples.\n\n    Build during bot startup, never during a request. Each 64-bit entry is\n    (score << 36) | pair_mask; arrays together occupy about 30 MiB. The\n    explicit index argument keeps decision helpers independent of state.\n    """\n    table = get_table()\n    index = {}\n    for triple in combinations(range(36), 3):\n        board_mask = sum(1 << c for c in triple)\n        live = [1 << c for c in range(36) if c not in triple]\n        ranked = [(table[a | b | board_mask] << 36) | a | b\n                  for a, b in combinations(live, 2)]\n        ranked.sort(reverse=True)\n        index[board_mask] = array(\'Q\', ranked)\n    return index\n\n\ndef analyze(hole, board, index=None):\n    """Compare all feasible opponent two-card pairs, with exact removal.\n\n    Any live pair extends to a legal five-card opponent hand, so this is\n    equivalent to enumerating all five-card hands, at much lower cost.\n    public_best ignores hero cards; opponent_best removes them. Blockers\n    count unavailable pairs achieving public_best, not opponent hand mass.\n    """\n    hole, board = tuple(hole), tuple(board)\n    if len(hole) != 5 or len(board) not in (3, 4, 5):\n        raise ValueError(\'expected five hole cards and flop/turn/river board\')\n    if len(set(hole + board)) != len(hole + board) or any(c not in range(36) for c in hole + board):\n        raise ValueError(\'cards must be distinct integers in 0..35\')\n    table = get_table()\n    triples = tuple((1 << a) | (1 << b) | (1 << c) for a, b, c in combinations(board, 3))\n    if index is not None:\n        own_mask = sum(1 << c for c in hole)\n        board_mask = sum(1 << c for c in board)\n        pair_bits = (1 << 36) - 1\n        score = max(table[(1 << a) | (1 << b) | triple]\n                    for a, b in combinations(hole, 2) for triple in triples)\n        opponent_best = public_best = 0\n        public_pairs = set()\n        for triple in triples:\n            local_best = None\n            found_opponent = False\n            for packed in index[triple]:\n                pair = packed & pair_bits\n                if pair & board_mask:\n                    continue\n                value = packed >> 36\n                if local_best is None:\n                    local_best = value\n                if value < local_best and found_opponent:\n                    break\n                if value > public_best:\n                    public_best = value\n                    public_pairs = {pair}\n                elif value == public_best:\n                    public_pairs.add(pair)\n                if not found_opponent and not pair & own_mask:\n                    opponent_best = max(opponent_best, value)\n                    found_opponent = True\n        return NutInfo(score, opponent_best, public_best,\n                       sum(bool(pair & own_mask) for pair in public_pairs), len(public_pairs))\n    own = set(hole)\n    available = [c for c in range(36) if c not in board]\n    score = opponent_best = public_best = count = blocked = 0\n    for a, b in combinations(available, 2):\n        mask = (1 << a) | (1 << b)\n        value = 0\n        for triple in triples:\n            candidate = table[mask | triple]\n            if candidate > value:\n                value = candidate\n        removed = a in own or b in own\n        if a in own and b in own:\n            score = max(score, value)\n        if not removed:\n            opponent_best = max(opponent_best, value)\n        if value > public_best:\n            public_best, count, blocked = value, 1, int(removed)\n        elif value == public_best:\n            count += 1\n            blocked += int(removed)\n    return NutInfo(score, opponent_best, public_best, blocked, count)\n\n\ndef nut_outs(hole, board, candidates=None, index=None):\n    """Sorted unseen next cards making an unbeaten made hand.\n\n    Exact and deterministic, intended for offline analysis or a bounded\n    candidate subset at runtime. Does not assume an opponent\'s range.\n    """\n    if len(board) not in (3, 4):\n        raise ValueError(\'nut outs require a flop or turn\')\n    dead = set(hole) | set(board)\n    live = range(36) if candidates is None else sorted(set(candidates))\n    return tuple(c for c in live if c not in dead and analyze(hole, (*board, c), index).is_nuts)\n\n\ndef flush_candidates(hole, board):\n    """Cards completing a possible Omaha flush on the next street.\n\n    This candidate filter is cheap; nut_outs still checks all stronger hand\n    categories, including quads and straight flushes, after completion.\n    """\n    suits = [s for s in range(4) if sum((c & 3) == s for c in hole) >= 2\n             and sum((c & 3) == s for c in board) == 2]\n    dead = set(hole) | set(board)\n    return tuple(c for c in range(36) if c not in dead and (c & 3) in suits)\n', 'lib.oppstats': '"""Opponent stats tracker: pure functions over a plain dict kept in the bot\'s `memory`.\n\nUsage in a bot (lib holds no state; it is reloaded every half):\n\n    new_half:        memory["opp"] = oppstats.new_stats()\n    choose_action:   oppstats.observe(memory["opp"], obs)            # idempotent per hand\n    on_hand_end:     oppstats.hand_end(memory["opp"], result)\n    read:            oppstats.estimate(stats, "fold_half", seat="bb")  -> (smoothed value, n)\n\n"Opp" is always the opponent; `seat` is the OPPONENT\'s seat: "btn" (small blind, acts first preflop and\nlast postflop) or "bb". seat=None sums both. `street` is 0..3 (Street value) or None for all streets.\n\nWhat we see vs what happened. An obs shows the history up to our decision, not our own current action nor\nwhat the opp did afterwards. observe() consumes only the unseen history items per hand (so calling it\nrepeatedly with the same prefix is safe). The rest is reconstructed in hand_end() from the last obs and the\nHandResult (chip counts pin down our last action and its size, and the opp\'s reply):\n  * opp is the button and folds preflop before we ever act (we never got an obs): my_net == +1\n  * opp folds to our last raise (winner "me", no showdown): fold facing our half/pot raise\n  * showdown right after our last action: opp CALLs our raise, or CHECKs behind our river check\nReconstruction needs no extra API call; note_action(stats, action) is NOT required.\nUnobserved hands (no obs and not a button fold, e.g. an emptied time bank) only bump stats["unobserved"].\n\nDefinitions (all per opp seat, with Beta smoothing in estimate()):\n  vpip        opp put chips in voluntarily preflop (raise, or call a bet/blind; a BB check is not voluntary)\n  pfr         opp raised preflop            (vpip and pfr: share of hands where opp acted preflop)\n  fold_half / fold_pot / fold_raise   opp folds when facing OUR half-pot / pot / any raise (street-aware)\n  call_down   opp calls (does not fold or re-raise) when facing our raise\n  agg_freq    opp raises / (raises + calls + checks); aggression_factor() = raises / calls, smoothed\n  wtsd        showdowns / hands that reached the flop;   wsd = opp\'s showdown win share (split = 0.5)\n\nestimate() never raises; every mutator catches exceptions, counts them in stats["errors"] and keeps\nthe message in stats["last_error"] (tests assert errors == 0).\n"""\n\nfrom game import STARTING_STACK, Action, Street\n\nSHOWDOWN_LOG_CAP = 200\nPENDING_CAP = 8\nCONF_K = 20.0  # confidence = n / (n + CONF_K) in vector()\n\nSEATS = ("btn", "bb")\nSIZES = ("h", "p", "u")  # our raise size the opp faces: half pot, pot, unknown (reconstructed, ambiguous)\n\n# (prior mean, prior strength) for the Beta smoothing. Neutral guesses until re-fit from real matches.\nPRIORS = {\n    "vpip": (0.60, 6.0),\n    "pfr": (0.30, 6.0),\n    "fold_half": (0.35, 4.0),\n    "fold_pot": (0.45, 4.0),\n    "fold_raise": (0.40, 4.0),\n    "call_down": (0.50, 4.0),\n    "agg_freq": (0.35, 6.0),\n    "wtsd": (0.40, 6.0),\n    "wsd": (0.50, 6.0),\n}\nSTAT_NAMES = tuple(PRIORS)\n\n_STREET_KEYS = tuple(f"{k}_{s}" for s in SIZES for k in ("faced", "fold", "call", "raise")) + (\n    "agg_raise", "agg_call", "open", "check")\n_SEAT_KEYS = ("hands", "flops", "sd", "sd_opp", "sd_split", "vpip_n", "vpip", "pfr")\n\n\ndef new_stats() -> dict:\n    """Fresh stats dict (plain ints/lists/dicts, JSON-able except int keys of \'pending\')."""\n    return {\n        "seat": {s: {**{k: 0 for k in _SEAT_KEYS}, "st": [{k: 0 for k in _STREET_KEYS} for _ in range(4)]}\n                 for s in SEATS},\n        "pending": {},          # hand_index -> in-progress hand state\n        "last_done": -1,        # highest hand_index already finalized\n        "showdowns": [],        # last SHOWDOWN_LOG_CAP showdown records\n        "unobserved": 0,        # hands ended with no obs and no reconstructable opp action\n        "recon_fail": 0,        # reconstruction found inconsistent chip counts\n        "errors": 0,\n        "last_error": None,\n    }\n\n\n# ----- updates ----------------------------------------------------------------------------------\n\ndef observe(stats: dict, obs) -> None:\n    """Call from choose_action with the obs (before deciding). Safe to call repeatedly per hand."""\n    try:\n        hi = obs.hand_index\n        if hi <= stats["last_done"]:\n            return\n        pending = stats["pending"]\n        hs = pending.get(hi)\n        if hs is None:\n            hs = _new_hand(hi, "bb" if obs.is_button else "btn")\n            pending[hi] = hs\n            while len(pending) > PENDING_CAP:\n                del pending[min(pending)]\n        hist = obs.action_history\n        for i in range(hs["consumed"], len(hist)):\n            it = hist[i]\n            _apply(stats, hs, (int(it.street), bool(it.is_me), int(it.action), it.amount, it.street_total))\n        hs["consumed"] = max(hs["consumed"], len(hist))\n        _set_street(hs, int(obs.street))\n        ra = obs.raise_to\n        hs["last"] = {\n            "street": int(obs.street), "to_call": obs.to_call, "my_bet": obs.my_bet,\n            "opp_bet": obs.opp_bet, "my_stack": obs.my_stack, "opp_stack": obs.opp_stack,\n            "rh": ra.get(Action.RAISE_HALF), "rp": ra.get(Action.RAISE_POT),\n        }\n    except Exception as e:  # noqa: BLE001 - a stats bug must never cost a bot the match\n        _fail(stats, e)\n\n\ndef hand_end(stats: dict, result) -> None:\n    """Call from on_hand_end. Handles batched calls (several results with no obs in between)."""\n    try:\n        hi = result.hand_index\n        if hi <= stats["last_done"]:\n            return\n        hs = stats["pending"].pop(hi, None)\n        if hs is None:\n            hs = _unobserved_hand(stats, result)\n            if hs is None:\n                stats["last_done"] = hi\n                return\n            _finish(stats, hs, result, recon=False)\n        else:\n            _finish(stats, hs, result, recon=True)\n        stats["last_done"] = hi\n        for k in [k for k in stats["pending"] if k < hi]:  # their on_hand_end will never come\n            del stats["pending"][k]\n    except Exception as e:  # noqa: BLE001\n        _fail(stats, e)\n\n\ndef feed_hand(stats: dict, opp_is_button: bool, records, result) -> None:\n    """Training/offline: ingest one FULL hand (no reconstruction). records = iterable of\n    (street, is_me, action, amount, street_total) from our point of view, e.g. from exported hand histories."""\n    try:\n        hs = _new_hand(result.hand_index, "btn" if opp_is_button else "bb")\n        for r in records:\n            _apply(stats, hs, (int(r[0]), bool(r[1]), int(r[2]), r[3], r[4]))\n        _finish(stats, hs, result, recon=False)\n        stats["last_done"] = max(stats["last_done"], result.hand_index)\n    except Exception as e:  # noqa: BLE001\n        _fail(stats, e)\n\n\ndef _fail(stats: dict, e: Exception) -> None:\n    try:\n        stats["errors"] += 1\n        stats["last_error"] = f"{type(e).__name__}: {e}"\n    except Exception:  # noqa: BLE001\n        pass\n\n\ndef _new_hand(hand_index: int, opp_seat: str) -> dict:\n    return {"hand": hand_index, "seat": opp_seat, "consumed": 0, "street": 0,\n            "facing": "blind" if opp_seat == "btn" else None,  # the button\'s first decision faces the BB\n            "opp_acted": False, "pre": False, "vp": False, "pf": False, "seq": [], "last": None}\n\n\ndef _set_street(hs: dict, street: int) -> None:\n    if street != hs["street"]:\n        hs["street"] = street\n        hs["facing"] = None\n        hs["opp_acted"] = False\n\n\ndef _apply(stats: dict, hs: dict, rec: tuple) -> None:\n    """Apply one action record (street, is_me, action, amount, street_total) in order."""\n    street, is_me, action = rec[0], rec[1], rec[2]\n    _set_street(hs, street)\n    hs["seq"].append(rec)\n    if is_me:\n        hs["facing"] = _size(action)  # the opp now faces our raise (None after a check/call/fold)\n        return\n    sd = stats["seat"][hs["seat"]]\n    st = sd["st"][street]\n    f = hs["facing"]\n    if street == 0 and not hs["pre"]:\n        hs["pre"] = True\n        sd["vpip_n"] += 1\n    voluntary = False\n    if action == Action.FOLD:\n        if f in SIZES:\n            st["faced_" + f] += 1\n            st["fold_" + f] += 1\n    elif action == Action.CHECK_CALL:\n        if f in SIZES:\n            st["faced_" + f] += 1\n            st["call_" + f] += 1\n            st["agg_call"] += 1\n        elif f == "blind":\n            st["agg_call"] += 1\n        else:\n            st["check"] += 1\n        voluntary = street == 0 and f is not None\n    else:\n        st["agg_raise"] += 1\n        if f in SIZES:\n            st["faced_" + f] += 1\n            st["raise_" + f] += 1\n        else:\n            st["open"] += 1\n        voluntary = street == 0\n        if voluntary and not hs["pf"]:\n            hs["pf"] = True\n            sd["pfr"] += 1\n    if voluntary and not hs["vp"]:\n        hs["vp"] = True\n        sd["vpip"] += 1\n    hs["opp_acted"] = True\n    hs["facing"] = None\n\n\ndef _size(action: int):\n    return "h" if action == Action.RAISE_HALF else "p" if action == Action.RAISE_POT else None\n\n\ndef _unobserved_hand(stats: dict, result):\n    """A hand with no obs: either the button opp folded preflop (we are BB; +1 chip), or unknown."""\n    if result.my_net == 1 and not result.went_to_showdown and result.winner == "me":\n        hs = _new_hand(result.hand_index, "btn")\n        _apply(stats, hs, (0, False, int(Action.FOLD), 0, 1))  # SB folds: total 1 chip in\n        return hs\n    stats["unobserved"] += 1\n    if result.went_to_showdown and result.opp_hole is not None:\n        _log_showdown(stats, None, result, [])\n    return None\n\n\ndef _finish(stats: dict, hs: dict, result, recon: bool) -> None:\n    if recon and hs["last"] is not None:\n        try:\n            _reconstruct(stats, hs, result, hs["last"])\n        except Exception as e:  # noqa: BLE001\n            stats["recon_fail"] += 1\n            _fail(stats, e)\n    sd = stats["seat"][hs["seat"]]\n    sd["hands"] += 1\n    if len(result.board) >= 3:\n        sd["flops"] += 1\n    if result.went_to_showdown:\n        sd["sd"] += 1\n        if result.winner == "opp":\n            sd["sd_opp"] += 1\n        elif result.winner == "split":\n            sd["sd_split"] += 1\n        if result.opp_hole is not None:\n            _log_showdown(stats, hs["seat"], result, hs["seq"])\n\n\ndef _log_showdown(stats: dict, seat, result, seq) -> None:\n    log = stats["showdowns"]\n    log.append({"hand": result.hand_index, "opp_seat": seat, "opp_hole": tuple(result.opp_hole),\n                "board": tuple(result.board), "winner": result.winner, "seq": list(seq)})\n    if len(log) > SHOWDOWN_LOG_CAP:\n        del log[: len(log) - SHOWDOWN_LOG_CAP]\n\n\ndef _reconstruct(stats: dict, hs: dict, r, L: dict) -> None:\n    """Add our last action and the opp\'s unseen reply, from the last obs `L` and the result `r`."""\n    st = L["street"]\n    c_me0 = STARTING_STACK - L["my_stack"]\n    if r.went_to_showdown:\n        c_me = r.pot // 2\n    elif r.winner == "me":  # opp folded: opp\'s chips in == what we won\n        c_me = r.pot - r.my_net\n    elif r.winner == "opp":  # we folded at L\n        _apply(stats, hs, (st, True, int(Action.FOLD), 0, L["my_bet"]))\n        return\n    else:\n        stats["recon_fail"] += 1\n        return\n    added = c_me - c_me0\n    if added > L["to_call"] and (L["rh"] is not None or L["rp"] is not None):\n        total = L["my_bet"] + added\n        # half and pot can land on the same total (min-raise / all-in clamps): then the size is unknowable\n        size = "u" if L["rh"] == L["rp"] else "p" if total == L["rp"] else "h" if total == L["rh"] else "u"\n        _apply(stats, hs, (st, True, int(Action.RAISE_HALF if size == "h" else Action.RAISE_POT), added, total))\n        hs["facing"] = size\n        if r.went_to_showdown:\n            _apply(stats, hs, (st, False, int(Action.CHECK_CALL), total - L["opp_bet"], total))\n        else:\n            _apply(stats, hs, (st, False, int(Action.FOLD), 0, L["opp_bet"]))\n        return\n    _apply(stats, hs, (st, True, int(Action.CHECK_CALL), added, L["my_bet"] + added))\n    if r.went_to_showdown:\n        if L["to_call"] == 0 and not hs["opp_acted"]:  # we checked first on the river; opp checked behind\n            _apply(stats, hs, (st, False, int(Action.CHECK_CALL), 0, L["opp_bet"]))\n    else:  # opp can only fold facing a raise of ours\n        stats["recon_fail"] += 1\n\n\n# ----- reading ----------------------------------------------------------------------------------\n\ndef hands(stats: dict, seat: str | None = None) -> int:\n    """Finalized hands (per opp seat, or both)."""\n    return sum(stats["seat"][s]["hands"] for s in _seats(seat))\n\n\ndef estimate(stats: dict, name: str, seat: str | None = None, street: int | None = None) -> tuple[float, int]:\n    """(Beta-smoothed value, n) for a stat in STAT_NAMES; n = opportunities. Prior mean when n == 0.\n    Never raises: bad input returns (prior mean, 0)."""\n    try:\n        return _value(name, _counts(stats, seat, street))\n    except Exception:  # noqa: BLE001\n        return PRIORS.get(name, (0.5, 1.0))[0], 0\n\n\ndef aggression_factor(stats: dict, seat: str | None = None, street: int | None = None) -> tuple[float, int]:\n    """(raises + 1) / (calls + 1), n = raises + calls. 1.0 with no data."""\n    try:\n        c = _counts(stats, seat, street)\n        return (c["agg_raise"] + 1) / (c["agg_call"] + 1), c["agg_raise"] + c["agg_call"]\n    except Exception:  # noqa: BLE001\n        return 1.0, 0\n\n\ndef _seats(seat):\n    return SEATS if seat is None else (seat,)\n\n\ndef _counts(stats: dict, seat, street) -> dict:\n    c = {k: 0 for k in _SEAT_KEYS + _STREET_KEYS}\n    for s in _seats(seat):\n        sd = stats["seat"][s]\n        for k in _SEAT_KEYS:\n            c[k] += sd[k]\n        for st in (sd["st"] if street is None else (sd["st"][street],)):\n            for k in _STREET_KEYS:\n                c[k] += st[k]\n    return c\n\n\ndef _smooth(k: float, n: float, name: str) -> tuple[float, int]:\n    mean, strength = PRIORS[name]\n    return (k + mean * strength) / (n + strength), int(n)\n\n\ndef _value(name: str, c: dict) -> tuple[float, int]:\n    if name == "vpip":\n        return _smooth(c["vpip"], c["vpip_n"], name)\n    if name == "pfr":\n        return _smooth(c["pfr"], c["vpip_n"], name)\n    if name == "fold_half":\n        return _smooth(c["fold_h"], c["faced_h"], name)\n    if name == "fold_pot":\n        return _smooth(c["fold_p"], c["faced_p"], name)\n    faced = c["faced_h"] + c["faced_p"] + c["faced_u"]\n    if name == "fold_raise":\n        return _smooth(c["fold_h"] + c["fold_p"] + c["fold_u"], faced, name)\n    if name == "call_down":\n        return _smooth(c["call_h"] + c["call_p"] + c["call_u"], faced, name)\n    if name == "agg_freq":\n        return _smooth(c["agg_raise"], c["agg_raise"] + c["agg_call"] + c["check"], name)\n    if name == "wtsd":\n        return _smooth(c["sd"], c["flops"], name)\n    if name == "wsd":\n        return _smooth(c["sd_opp"] + 0.5 * c["sd_split"], c["sd"], name)\n    raise KeyError(name)\n\n\n# ----- feature vector ---------------------------------------------------------------------------\n\nVECTOR_STATS = ("vpip", "pfr", "fold_half", "fold_pot", "call_down", "agg_freq", "wtsd", "wsd")\nVECTOR_DIM = 3 * len(VECTOR_STATS) * 2 + 2 * 4\n\n\ndef vector(stats: dict) -> list[float]:\n    """Fixed-length features (VECTOR_DIM). Order:\n      for group in (opp on button, opp in BB, both): for stat in VECTOR_STATS: value, confidence\n        (value = Beta-smoothed estimate, confidence = n / (n + CONF_K))      -> 3 * 8 * 2 = 48\n      then, over both seats, for street 0..3: agg_freq, fold_raise                -> 8\n    Never raises: returns prior-only values on bad input."""\n    try:\n        out: list[float] = []\n        for seat in ("btn", "bb", None):\n            c = _counts(stats, seat, None)\n            for name in VECTOR_STATS:\n                v, n = _value(name, c)\n                out += [v, n / (n + CONF_K)]\n        for street in range(4):\n            c = _counts(stats, None, street)\n            out += [_value("agg_freq", c)[0], _value("fold_raise", c)[0]]\n        return out\n    except Exception:  # noqa: BLE001\n        return vector(new_stats())\n', 'lib.preflop': '"""Preflop hand classes up to suit isomorphism. Pure helpers, no state.\n\nA 5-card hand\'s class is its four per-suit rank bitmasks, sorted descending, packed into one int.\ncard = rank * 4 + suit (evaluator convention), rank 0..8 -> bit `rank` of the suit\'s mask.\n"""\n\nfrom itertools import combinations\n\n\ndef canon_key(hole) -> int:\n    """Suit-isomorphism class key of a 5-card hand (any card order)."""\n    m = [0, 0, 0, 0]\n    for c in hole:\n        m[c & 3] |= 1 << (c >> 2)\n    m.sort(reverse=True)\n    return (m[0] << 27) | (m[1] << 18) | (m[2] << 9) | m[3]\n\n\ndef key_to_hand(key: int) -> list[int]:\n    """Representative hand (sorted cards) of a class key."""\n    hand = []\n    for suit, shift in enumerate((27, 18, 9, 0)):\n        mask = (key >> shift) & 0x1FF\n        hand += [r * 4 + suit for r in range(9) if mask >> r & 1]\n    return sorted(hand)\n\n\ndef all_keys() -> list[int]:\n    """Every class key, sorted ascending."""\n    return sorted({canon_key(h) for h in combinations(range(36), 5)})\n\n\nclass PreflopTable:\n    """Equity per class vs a random hand, read from a table.npy written by train/train_preflop_table.py.\n\n    Load once at import (not in the time bank). `eq(hole)` is a dict lookup plus canon_key (~5 us).\n    """\n\n    def __init__(self, path):\n        import numpy as np\n\n        t = np.load(path)\n        self.eqs = {int(k): float(e) for k, e in zip(t["key"], t["eq"])}\n        order = np.argsort(t["eq"], kind="stable")\n        self._sorted_eq = t["eq"][order]\n        self._cum_w = np.cumsum(t["w"][order].astype(np.int64))  # hands at or below each class\n        self.total = int(self._cum_w[-1])\n\n    def eq(self, hole) -> float:\n        return self.eqs[canon_key(hole)]\n\n    def percentile(self, hole) -> float:\n        """Share of all 5-card hands with strictly lower equity (0 = worst, ~1 = best)."""\n        import numpy as np\n\n        i = int(np.searchsorted(self._sorted_eq, self.eq(hole), side="left"))\n        return (int(self._cum_w[i - 1]) if i else 0) / self.total\n\n    def eq_at_percentile(self, pct: float) -> float:\n        """Smallest equity such that at least `pct` of hands lie strictly below it (hands >= it are the top 1-pct)."""\n        import numpy as np\n\n        i = int(np.searchsorted(self._cum_w, pct * self.total, side="left"))\n        return float(self._sorted_eq[min(i, len(self._sorted_eq) - 1)])\n', 'lib.pushfold': '"""Legal restricted preflop commitment game; no policy sees hidden cards."""\nfrom game import Action, Street\n\n\ndef restricted_actions(obs):\n    """Strategic preflop fold/call/pot, forced postflop pot/call continuation."""\n    if obs.street == Street.PREFLOP:\n        return tuple(a for a in obs.legal_actions if a != Action.RAISE_HALF)\n    if Action.RAISE_POT in obs.legal_actions:\n        return (Action.RAISE_POT,)\n    return (Action.CHECK_CALL,)\n\n\ndef information_key(obs):\n    """Perfect recall, own cards only; no bucket or opponent-card leakage."""\n    return (\n        obs.is_button, tuple(obs.hole_cards), tuple(obs.board),\n        tuple((int(h.street), h.is_me, int(h.action), h.amount, h.street_total)\n              for h in obs.action_history),\n    )\n', 'lib.rules': '"""Equity-threshold decision rule, shared by every bot that turns an equity estimate into an action\n(Monte Carlo in archetype.py, a neural net in equity_net/, ...)."""\n\nfrom game import Action, Street\n\nRULE_PARAMS = {\n    "open_eq": 0.50,     # preflop: min equity vs a random hand to put more chips in\n    "raise_eq": 0.70,    # min equity to raise\n    "call_margin": 0.0,  # call if equity >= pot odds + margin\n    "bluff": 0.0,        # chance to raise anyway when nobody has raised this street\n    "slowplay": 0.0,     # chance to just check/call a hand worth raising\n    "big_raise": True,   # prefer RAISE_POT over RAISE_HALF\n}\n\n\ndef decide(obs, eq: float, p: dict, rng) -> Action:\n    order = (Action.RAISE_POT, Action.RAISE_HALF) if p["big_raise"] else (Action.RAISE_HALF, Action.RAISE_POT)\n    raise_action = next((a for a in order if a in obs.legal_actions), None)\n    if raise_action is not None:\n        if eq >= p["raise_eq"] and rng.random() >= p["slowplay"]:\n            return raise_action\n        if obs.raises_this_street == 0 and rng.random() < p["bluff"]:\n            return raise_action\n    if obs.to_call == 0:\n        return Action.CHECK_CALL\n    need = obs.to_call / (obs.pot + obs.to_call) + p["call_margin"]\n    if obs.street == Street.PREFLOP:\n        need = max(need, p["open_eq"])\n    return Action.CHECK_CALL if eq >= need else Action.FOLD\n', 'lib.threshold_fit': '"""Opponent equity-threshold fitting from showdowns (category 5.4).\n\nMany field bots are "equity vs a random hand" threshold players: raise if eq >= R, else call if\neq >= pot odds + M (preflop: eq >= open), else fold. At every showdown we see opp_hole, so we can replay\nthe hand from lib.oppstats\' showdown log, compute the equity the opponent held at each of its decisions,\nand fit R and M directly.\n\nUsage (state lives in the bot\'s memory; lib holds none):\n\n    new_half:     memory["tf"] = threshold_fit.new_fit()\n    on_hand_end:  oppstats.hand_end(memory["opp"], result)\n                  threshold_fit.update(memory["tf"], memory["opp"], memory["rng"])   # new showdowns only\n    read:         threshold_fit.fit(memory["tf"])  -> {"pre": {...}, "post": {...}}\n\nFit per group ("pre" = preflop, "post" = flop..river):\n  raise_t  threshold on eq separating raises from calls/checks where a raise was legal: maximum\n           likelihood of a probit with bluff/slowplay lapse rates (robust to a 70% slowplayer). Robust to\n           bluffs/slowplays (they just add errors on both sides). n_raise_*: sample sizes.\n  call_eq  / call_m  lower edge of eq (resp. eq - pot odds) over CALLS facing a bet. Folds never reach\n           showdown (censored), so this is a low quantile (CALL_Q) of what callers held; it reads high\n           with few samples and low when the opponent\'s own equity estimate is noisy.\n  open_t   ("pre" only) the opponent\'s first button decision is made with a uniformly random hand, so\n           its fold-or-play threshold is the eq quantile at 1 - vpip(btn) over random hands (OPEN_TABLE).\n           Needs no showdowns; pass the oppstats dict to fit().\nEvery value is None until its group has MIN_N samples. Never raises (errors counted in fit["errors"]).\n"""\n\nimport random\n\nimport numpy as np\n\nfrom game import STARTING_STACK, Action\nfrom lib import oppstats\nfrom lib.equity import _best, equity\n\nSAMPLES = 48     # Monte Carlo samples per opponent decision (fixed for determinism)\nREFIT_EVERY = 4  # refit after this many new showdowns\nMIN_N = 8        # decisions needed before a threshold is reported\nCALL_Q = 0.05    # quantile of callers\' eq used as the call threshold\nDECISION_CAP = 600  # oldest decisions dropped beyond this (bounded memory and fit cost)\n_RAISES = (Action.RAISE_HALF, Action.RAISE_POT)\n\n\ndef _open_table(n: int = 400, samples: int = 64) -> list[float]:\n    """Sorted preflop eq-vs-random of n random hands (fixed seed; ~0.1 s, paid at import)."""\n    rng = random.Random(12345)\n    return sorted(equity(sorted(rng.sample(range(36), 5)), [], rng, samples) for _ in range(n))\n\n\nOPEN_TABLE = _open_table()\n\n\ndef open_threshold(stats: dict) -> tuple[float | None, int]:\n    """(eq threshold of the opponent\'s button open/limp vs fold, n hands) from oppstats vpip."""\n    vpip, n = oppstats.estimate(stats, "vpip", seat="btn")\n    if n < MIN_N:\n        return None, n\n    return quantile(OPEN_TABLE, 1.0 - vpip), n\n\n\ndef new_fit() -> dict:\n    return {"done": -1, "dec": [], "errors": 0, "last_error": None, "cache": None}\n\n\ndef decisions(rec: dict) -> list[tuple]:\n    """Opponent decisions in a showdown record: (street, board_len, to_call, pot, raise_legal, action).\n    Replays the chip flow from the blinds; seq items are (street, is_me, action, amount, street_total)."""\n    opp_btn = rec["opp_seat"] == "btn"\n    bet = {True: 2 if opp_btn else 1, False: 1 if opp_btn else 2}  # is_me -> chips this street\n    put = dict(bet)  # is_me -> chips this hand\n    street, raises, out = 0, 0, []\n    for st, is_me, action, amount, _total in rec["seq"]:\n        if st != street:\n            street, raises, bet = st, 0, {True: 0, False: 0}\n        if not is_me:\n            to_call = bet[True] - bet[False]\n            legal = raises < 4 and STARTING_STACK - put[False] > to_call and STARTING_STACK - put[True] > 0\n            out.append((st, (0, 3, 4, 5)[st], to_call, put[True] + put[False], legal, int(action)))\n        bet[is_me] += amount\n        put[is_me] += amount\n        if action in _RAISES:\n            raises += 1\n    return out\n\n\ndef update(f: dict, stats: dict, rng: random.Random | None = None, samples: int = SAMPLES) -> None:\n    """Score every showdown in the oppstats log newer than the last call. Seeded rng -> deterministic."""\n    try:\n        rng = rng or random.Random(0)\n        for rec in stats["showdowns"]:\n            if rec["hand"] <= f["done"] or rec["opp_seat"] is None:\n                continue\n            hole, board = list(rec["opp_hole"]), list(rec["board"])\n            for st, blen, to_call, pot, legal, action in decisions(rec):\n                eq = equity(hole, board[:blen], rng, samples)\n                f["dec"].append((st, round(eq, 4), to_call, pot, legal, action))\n            f["done"] = rec["hand"]\n            f["fresh"] = f.get("fresh", 0) + 1\n            if f["cache"] is None or f["fresh"] >= REFIT_EVERY:  # refit cost: ~3 ms per group\n                f["cache"], f["fresh"] = None, 0\n        if len(f["dec"]) > DECISION_CAP:\n            del f["dec"][: len(f["dec"]) - DECISION_CAP]\n    except Exception as e:  # noqa: BLE001 - never cost the bot an error\n        f["errors"] += 1\n        f["last_error"] = f"{type(e).__name__}: {e}"\n\n\n# probit-with-lapses grid: P(raise | eq) = lo + (1 - lo - hi) * Phi((eq - t) / sigma)\n#   lo = bluff rate below t, hi = slowplay rate above t, sigma = the opponent\'s own equity noise\n_T = np.linspace(0.0, 1.0, 101)\n_SIG = np.array([0.03, 0.06, 0.10])\n_LO = np.array([0.01, 0.1, 0.25])\n_HI = np.array([0.01, 0.3, 0.6])\n_NB = 50\n_X = (np.arange(_NB) + 0.5) / _NB  # bin centres\n\n\ndef step_threshold(pos: list[float], neg: list[float]) -> tuple[float | None, int]:\n    """Maximum-likelihood threshold t of P(raise | eq) over a (t, sigma, lo, hi) grid, numpy-vectorized."""\n    if not pos or not neg:\n        return None, len(pos) + len(neg)\n    # sufficient statistics: raises / decisions per 0.02 eq bin (cost independent of N)\n    k = np.bincount(np.minimum((np.array(pos) * _NB).astype(int), _NB - 1), minlength=_NB)\n    n = k + np.bincount(np.minimum((np.array(neg) * _NB).astype(int), _NB - 1), minlength=_NB)\n    z = (_X[None, None, :] - _T[:, None, None]) / _SIG[None, :, None]           # (T, S, B)\n    phi = 0.5 * (1.0 + _erf(z / np.sqrt(2.0)))\n    p = _LO[None, None, :, None, None] + (1 - _LO[None, None, :, None, None] - _HI[None, None, None, :, None])         * phi[:, :, None, None, :]                                               # (T, S, L, H, B)\n    ll = (k * np.log(p) + (n - k) * np.log1p(-p)).sum(axis=-1)\n    t = np.unravel_index(np.argmax(ll), ll.shape)[0]\n    return round(float(_T[t]), 3), len(pos) + len(neg)\n\n\ndef _erf(x):\n    """Abramowitz-Stegun 7.1.26 (|err| < 1.5e-7): numpy has no erf and scipy isn\'t installed."""\n    s = np.sign(x)\n    a = np.abs(x)\n    t = 1.0 / (1.0 + 0.3275911 * a)\n    y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592)         * t * np.exp(-a * a)\n    return s * y\n\n\ndef quantile(xs: list[float], q: float) -> float:\n    s = sorted(xs)\n    return s[min(len(s) - 1, int(q * len(s)))]\n\n\ndef fit(f: dict, stats: dict | None = None) -> dict:\n    """{"pre"|"post": {"raise_t", "call_eq", "call_m", "n_raise", "n_call"}}, "pre" also "open_t"/"n_open"\n    (None without `stats`). Showdown part cached until new data."""\n    try:\n        if f["cache"] is None:\n            f["cache"] = {g: _fit_group([d for d in f["dec"] if (d[0] == 0) == (g == "pre")])\n                          for g in ("pre", "post")}\n        out = {"pre": dict(f["cache"]["pre"]), "post": f["cache"]["post"]}\n        out["pre"]["open_t"], out["pre"]["n_open"] = open_threshold(stats) if stats else (None, 0)\n        return out\n    except Exception as e:  # noqa: BLE001\n        f["errors"] += 1\n        f["last_error"] = f"{type(e).__name__}: {e}"\n        return {g: _fit_group([]) for g in ("pre", "post")}\n\n\ndef _fit_group(dec: list[tuple]) -> dict:\n    pos = [d[1] for d in dec if d[4] and d[5] in _RAISES]\n    neg = [d[1] for d in dec if d[4] and d[5] == Action.CHECK_CALL]\n    calls = [(d[1], d[1] - d[2] / (d[3] + d[2])) for d in dec if d[2] > 0 and d[5] == Action.CHECK_CALL]\n    raise_t, n_raise = step_threshold(pos, neg) if len(pos) + len(neg) >= MIN_N else (None, len(pos) + len(neg))\n    ok = len(calls) >= MIN_N\n    return {\n        "raise_t": raise_t, "n_raise": n_raise, "n_call": len(calls),\n        "call_eq": quantile([c[0] for c in calls], CALL_Q) if ok else None,\n        "call_m": quantile([c[1] for c in calls], CALL_Q) if ok else None,\n    }\n\n\ndef range_equity(hole, board, rng: random.Random, raise_t: float, samples: int = 64,\n                 inner: int = 8, min_hits: int = 6) -> float | None:\n    """Our showdown equity vs the opponent hands that would have raised: hands whose own equity vs a\n    random hand on this board (opp doesn\'t see our cards) is >= raise_t. None if fewer than min_hits of\n    `samples` opponent hands qualify (caller falls back to plain equity). Deterministic for a seeded rng."""\n    gen = np.random.default_rng(rng.getrandbits(64))\n    need = 5 - len(board)\n    b = np.array(board, dtype=np.int64)\n    # opponent hand + our runout: random permutation of the live cards (dead cards sorted last)\n    dead = np.zeros(36)\n    dead[list(hole) + list(board)] = 2.0\n    d = np.argsort(gen.random((samples, 36)) + dead, axis=1)[:, : 5 + need]\n    opp, run = d[:, :5], np.concatenate([np.broadcast_to(b, (samples, len(board))), d[:, 5:]], axis=1)\n    # the opponent\'s view: a random villain + runout from everything but its hand and the board\n    dead_o = np.zeros((samples, 36))\n    dead_o[:, list(board)] = 2.0\n    np.put_along_axis(dead_o, opp, 2.0, axis=1)\n    v = np.argsort(gen.random((samples, inner, 36)) + dead_o[:, None, :], axis=2)[:, :, : 5 + need]\n    v = v.reshape(samples * inner, 5 + need)\n    vrun = np.concatenate([np.broadcast_to(b, (len(v), len(board))), v[:, 5:]], axis=1)\n    one = np.int64(1)\n    o_s = _best(one << np.repeat(opp, inner, axis=0), one << vrun)\n    v_s = _best(one << v[:, :5], one << vrun)\n    opp_eq = ((o_s > v_s) + 0.5 * (o_s == v_s)).reshape(samples, inner).mean(axis=1)\n    keep = opp_eq >= raise_t\n    if keep.sum() < min_hits:\n        return None\n    me = _best(np.broadcast_to(one << np.array(hole, dtype=np.int64), (samples, 5)), one << run)\n    op = _best(one << opp, one << run)\n    return float(((me > op) + 0.5 * (me == op))[keep].mean())\n'}
import importlib.abc as _abc, importlib.util as _util, sys as _sys


class _InlineLib(_abc.MetaPathFinder, _abc.Loader):
    """Serves the inlined bots/lib sources to `import lib...` while this file loads."""

    def find_spec(self, name, path=None, target=None):
        if name in _LIB:
            return _util.spec_from_loader(name, self, is_package=name == "lib")

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        exec(compile(_LIB[module.__name__], f"<lib {module.__name__}>", "exec"), module.__dict__)


_hook = _InlineLib()
_sys.meta_path.insert(0, _hook)


from pathlib import Path

import numpy as np

from evaluator import warmup
from game import Action
from lib.abstraction import BettingTree, CardAbstraction

warmup()
HERE = Path(__file__).parent
TREE = BettingTree()
ABST = CardAbstraction(HERE / "abstraction.npz")
_x = np.load(HERE / "strategy.npz")
_b = np.load(HERE / "blueprint.npz")
STRATS = {"x": _x["strategy"], "bp": _b["strategy"], "c1": np.load(HERE / "c1.npz")["strategy"]}
ROW_OFFSET = _x["row_offset"]
assert np.array_equal(ROW_OFFSET, _b["row_offset"])
LLR = np.load(HERE / "switch.npz")["llr"].astype(np.float64)
LLR_C1 = np.load(HERE / "switch_c1.npz")["llr"].astype(np.float64)

PARAMS = {"on": 15.0, "off": 0.0, "min_actions": 50, "switch": True, "on_c1": 20.0, "off_c1": 0.0}


def new_half(config, memory: dict) -> None:
    memory["p"] = dict(PARAMS)
    memory["rng"] = np.random.default_rng(0)
    memory["bucket"] = {}
    memory["llr"] = 0.0
    memory["llr_c1"] = 0.0
    memory["n_opp"] = 0
    memory["mode"] = "x"
    memory["cur"] = -1
    memory["seq"] = []        # [(is_me, action int)] of the current hand, ours included
    memory["switches"] = 0


def _score(memory: dict, node: int, action: int) -> None:
    memory["llr"] += LLR[node, action]
    memory["llr_c1"] += LLR_C1[node, action]
    memory["n_opp"] += 1


def _update_mode(memory: dict) -> None:
    p = memory["p"]
    if not p["switch"] or memory["n_opp"] < p["min_actions"]:
        return
    mode, llr, llr_c1 = memory["mode"], memory["llr"], memory["llr_c1"]
    if mode == "bp":
        new = "bp" if llr >= p["off"] else ("c1" if llr_c1 > p["on_c1"] else "x")
    elif llr > p["on"]:
        new = "bp"
    elif mode == "c1":
        new = "c1" if llr_c1 >= p["off_c1"] else "x"
    else:
        new = "c1" if llr_c1 > p["on_c1"] else "x"
    if new != mode:
        memory["mode"] = new
        memory["switches"] += 1


def probs(obs, memory: dict, mode: str | None = None) -> np.ndarray | None:
    node = TREE.node_of_obs(obs)
    key = (obs.hand_index, len(obs.board))
    cache = memory["bucket"]
    if key not in cache:
        cache.clear()
        cache[key] = ABST.bucket(list(obs.hole_cards), list(obs.board))
    row = STRATS[mode or memory["mode"]][ROW_OFFSET[node] + cache[key]].astype(np.float64)
    if row.sum() == 0:
        return None
    return row / row.sum()


def choose_action(obs, memory: dict) -> Action:
    try:
        action = None
        p = probs(obs, memory)
        if p is not None:
            a = Action(int(memory["rng"].choice(4, p=p)))
            if a in obs.legal_actions:
                action = a
        if action is None:
            action = Action.CHECK_CALL
        memory["cur"] = obs.hand_index
        memory["seq"] = [(h.is_me, int(h.action)) for h in obs.action_history] + [(True, int(action))]
        return action
    except Exception:
        return Action.CHECK_CALL


def on_hand_end(result, memory: dict) -> None:
    try:
        if result.hand_index != memory["cur"]:
            # we never acted: the opponent was the button and folded its first action
            _score(memory, TREE.root, int(Action.FOLD))
        else:
            node = TREE.root
            for is_me, a in memory["seq"]:
                if not is_me:
                    _score(memory, node, a)
                node = TREE.children[node][a]
                if node is None or node < 0:
                    break
            if node is not None and node >= 0:
                # the opponent acted once more and ended the hand (no decision of ours followed)
                if not result.went_to_showdown and result.winner == "me":
                    _score(memory, node, int(Action.FOLD))
                elif result.went_to_showdown:
                    _score(memory, node, int(Action.CHECK_CALL))
        _update_mode(memory)
    except Exception:
        pass


# lib was imported above; drop the hook so it can't serve other code in this process.
_sys.meta_path.remove(_hook)
for _name in _LIB:
    _sys.modules.pop(_name, None)
